alter table app_user add column can_decide boolean not null default false;

create table assessor_trade (
    user_id uuid not null references app_user(id),
    trade varchar(120) not null,
    primary key (user_id, trade)
);

create table worker_profile (
    user_id uuid primary key references app_user(id),
    full_name varchar(120) not null,
    primary_trade varchar(120),
    years_experience int check (years_experience between 0 and 60),
    skills text,
    updated_at timestamptz not null default now()
);

create sequence case_number_seq;

-- id is generated by the client so offline creation and repeated sync are idempotent.
create table rpl_case (
    id uuid primary key,
    case_number varchar(20) not null unique default ('RPL-' || lpad(nextval('case_number_seq')::text, 6, '0')),
    worker_id uuid not null references app_user(id),
    trade varchar(120) not null,
    experience_years int not null check (experience_years between 0 and 60),
    skills text not null,
    details text,
    status varchar(24) not null check (status in ('DRAFT','NEW','AWAITING_QUALIFICATION','AWAITING_ASSESSOR',
        'IN_ASSESSMENT','EVIDENCE_REQUESTED','REPORT_PENDING','AWAITING_DECISION','DECIDED')),
    version int not null default 1,
    qualification_version_id uuid references qualification_version(id),
    qualification_confirmed_by uuid references app_user(id),
    qualification_confirmed_at timestamptz,
    assessor_id uuid references app_user(id),
    assigned_by uuid references app_user(id),
    assigned_at timestamptz,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    submitted_at timestamptz
);
create index on rpl_case(worker_id);
create index on rpl_case(assessor_id);

create table match_suggestion (
    id uuid primary key,
    case_id uuid not null references rpl_case(id),
    qualification_version_id uuid not null references qualification_version(id),
    confidence numeric(3,2) not null check (confidence between 0 and 1),
    explanation text not null,
    flagged boolean not null,
    source varchar(10) not null check (source in ('AI','KEYWORD')),
    created_at timestamptz not null default now()
);
create index on match_suggestion(case_id);

create table competency_score (
    case_id uuid not null references rpl_case(id),
    competency_id uuid not null references competency(id),
    score int not null check (score >= 0),
    comment text,
    updated_by uuid not null references app_user(id),
    updated_at timestamptz not null default now(),
    primary key (case_id, competency_id)
);

create table evidence (
    id uuid primary key,
    case_id uuid not null references rpl_case(id),
    competency_id uuid references competency(id),
    uploaded_by uuid not null references app_user(id),
    filename varchar(255) not null,
    content_type varchar(100) not null,
    size_bytes bigint not null,
    note text,
    created_at timestamptz not null default now()
);
create index on evidence(case_id);

create table evidence_request (
    id uuid primary key,
    case_id uuid not null references rpl_case(id),
    message text not null,
    requested_by uuid not null references app_user(id),
    created_at timestamptz not null default now(),
    fulfilled_at timestamptz
);
create index on evidence_request(case_id);

create table assessment_submission (
    case_id uuid primary key references rpl_case(id),
    recommendation varchar(20) not null check (recommendation in ('COMPETENT','NOT_YET_COMPETENT')),
    notes text,
    submitted_by uuid not null references app_user(id),
    submitted_at timestamptz not null default now(),
    ai_summary text,
    ai_generated_at timestamptz
);

create table final_decision (
    case_id uuid primary key references rpl_case(id),
    outcome varchar(20) not null check (outcome in ('COMPETENT','NOT_YET_COMPETENT')),
    rationale text,
    decided_by uuid not null references app_user(id),
    decided_at timestamptz not null default now()
);
